script:
function _qs(sel){return root_element.querySelector(sel);} 

function _routeFromData(btn){
  try{ return JSON.parse(btn.getAttribute('data-route')); }catch(e){ return null; }
}

function _wireMenu(){
  const menu = _qs('[data-menu]');
  if(!menu) return;
  menu.querySelectorAll('button[data-route]').forEach((btn)=>{
    btn.addEventListener('click', ()=>{
      const r = _routeFromData(btn);
      if(!r || !r.length) return;
      frappe.set_route.apply(frappe, r);
    });
  });

  const input = _qs('.tif-trustee__searchInput');
  if(input){
    input.addEventListener('input', ()=>{
      const q = (input.value||'').trim().toLowerCase();
      menu.querySelectorAll('button[data-route]').forEach((b)=>{
        const t = (b.textContent||'').toLowerCase();
        b.style.display = !q || t.includes(q) ? '' : 'none';
      });
    });
  }
}

_wireMenu();
